set -euo pipefail
export PYTHONDONTWRITEBYTECODE=1
export GIT_OPTIONAL_LOCKS=0
python3 -B - <<'PY'
import pathlib,os,subprocess,json,hashlib
base=pathlib.Path('/workspace')
def run(args,cwd=None):
 p=subprocess.run(args,cwd=cwd,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,timeout=20)
 return {'rc':p.returncode,'stdout':p.stdout,'stderr':p.stderr}
def info(p):
 if not p.is_file():return None
 h=hashlib.sha256()
 with p.open('rb') as f:
  for b in iter(lambda:f.read(1024*1024),b''):h.update(b)
 return {'path':str(p),'bytes':p.stat().st_size,'sha256':h.hexdigest()}
print('P3_READONLY_TOP '+json.dumps([{'name':p.name,'dir':p.is_dir(),'symlink':p.is_symlink()} for p in sorted(base.iterdir())]))
repos=[];hints=[]
prune={'.git','node_modules','__pycache__','lib','build','objects','dependencies','staged','vendor','tar-extracted'}
for root,dirs,files in os.walk(base):
 p=pathlib.Path(root);depth=len(p.relative_to(base).parts)
 if '.git' in dirs or '.git' in files:
  repos.append(p)
 if any(n in files for n in ['lakefile.lean','lakefile.toml','lake-manifest.json','EXTERNAL_SNAPSHOT.json','registry.json','compilation-registry.json']):
  hints.append({'path':str(p),'names':[n for n in files if n in {'lakefile.lean','lakefile.toml','lake-manifest.json','EXTERNAL_SNAPSHOT.json','registry.json','compilation-registry.json'}]})
 dirs[:]=[d for d in dirs if d not in prune and not d.startswith('.cache') and not pathlib.Path(root,d).is_symlink()]
 if depth>=5:dirs[:]=[]
print('P3_READONLY_HINTS '+json.dumps(hints))
for p in repos:
 head=run(['git','rev-parse','HEAD'],p)
 status=run(['git','status','--porcelain=v1','--untracked-files=no'],p)
 print('P3_READONLY_REPO '+json.dumps({'path':str(p),'head':head,'tracked_status':status}))
print('P3_READONLY_RUNTIME '+json.dumps({'lean':info(pathlib.Path('/toolchains/bin/lean')),'checker':info(pathlib.Path('/toolchains/bin/leanchecker')),'mathlib_head':run(['git','rev-parse','HEAD'],'/mathlib')}))
